from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)

    sum_result = 0
    product = 1

    for num in numbers:
        sum_result += num
        product *= num

    return (sum_result, product)
