Here is the Python script that solves this problem:

```python
from typing import List

def parse_music(music_string: str) -> List[int]:
    """ Input to this function is a string representing musical notes in special ASCII format.

    'o' - whole note lasts four beats
    'o|' - half note lasts two beats
    '.|' - quater note, which is 1 beat

    This script will return the number of beats for each type of note.
"""
    # Define a list to store the results
    result = []

    # Split the input string into parts based on whitespace
    parts = music_string.split(' ')

    # Iterate over the split parts and calculate the beat counts
    for part in parts:
        if 'o' in part:
            if 'o|' in part:
                result.append(2)
            elif '.|' in part:
                result.append(1)
            else:
                result.append(4)
        elif 'o|' in part:
            result.append(2)
        elif '.|' in part:
            result.append(1)
        else:
            if parts[0] == 'o':
                result.append(4)
            elif parts[0] == 'o|':
                result.append(2)
            elif parts[0] == '.|':
                result.append(1)

    return result
```

